class Solution {
public:
    int buildWall(int height, int width, vector<int>& bricks) {
        const int MOD = 1e9 + 7;
        vector<int> rows;
        function<void(int, int)> dfs = [&](int w, int mask) {
            if (w == width) {
                rows.push_back(mask);
                return;
            }
            for (int b : bricks) {
                if (w + b <= width) {
                    int nextMask = (w + b == width) ? mask : (mask | (1 << (w + b)));
                    dfs(w + b, nextMask);
                }
            }
        };
        dfs(0, 0);
        int r = rows.size();
        vector<vector<int>> adj(r);
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < r; j++) {
                if (!(rows[i] & rows[j])) adj[i].push_back(j);
            }
        }
        vector<long long> dp(r, 1);
        for (int h = 1; h < height; h++) {
            vector<long long> nextDp(r, 0);
            for (int i = 0; i < r; i++) {
                for (int j : adj[i]) {
                    nextDp[j] = (nextDp[j] + dp[i]) % MOD;
                }
            }
            dp = move(nextDp);
        }
        long long ans = 0;
        for (long long v : dp) ans = (ans + v) % MOD;
        return ans;
    }
};

class Solution {
    public int buildWall(int height, int width, int[] bricks) {
        final int MOD = 1_000_000_007;
        List<Integer> rows = new ArrayList<>();
        dfs(0, 0, width, bricks, rows);
        int r = rows.size();
        List<Integer>[] adj = new ArrayList[r];
        for (int i = 0; i < r; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < r; j++) {
                if ((rows.get(i) & rows.get(j)) == 0) adj[i].add(j);
            }
        }
        long[] dp = new long[r];
        Arrays.fill(dp, 1);
        for (int h = 1; h < height; h++) {
            long[] nextDp = new long[r];
            for (int i = 0; i < r; i++) {
                for (int j : adj[i]) {
                    nextDp[j] = (nextDp[j] + dp[i]) % MOD;
                }
            }
            dp = nextDp;
        }
        long ans = 0;
        for (long v : dp) ans = (ans + v) % MOD;
        return (int) ans;
    }
    private void dfs(int w, int mask, int width, int[] bricks, List<Integer> rows) {
        if (w == width) {
            rows.add(mask);
            return;
        }
        for (int b : bricks) {
            if (w + b <= width) {
                int nextMask = (w + b == width) ? mask : (mask | (1 << (w + b)));
                dfs(w + b, nextMask, width, bricks, rows);
            }
        }
    }
}

var buildWall = function(height, width, bricks) {
    const MOD = 1000000007;
    const rows = [];
    function dfs(w, mask) {
        if (w === width) {
            rows.push(mask);
            return;
        }
        for (const b of bricks) {
            if (w + b <= width) {
                const nextMask = (w + b === width) ? mask : (mask | (1 << (w + b)));
                dfs(w + b, nextMask);
            }
        }
    }
    dfs(0, 0);
    const r = rows.length;
    const adj = Array.from({ length: r }, () => []);
    for (let i = 0; i < r; i++) {
        for (let j = 0; j < r; j++) {
            if (!(rows[i] & rows[j])) adj[i].push(j);
        }
    }
    let dp = new Array(r).fill(1);
    for (let h = 1; h < height; h++) {
        const nextDp = new Array(r).fill(0);
        for (let i = 0; i < r; i++) {
            for (const j of adj[i]) {
                nextDp[j] = (nextDp[j] + dp[i]) % MOD;
            }
        }
        dp = nextDp;
    }
    return dp.reduce((a, b) => (a + b) % MOD, 0);
};
